/**
 * 將首頁區塊 CSS 合併為 `src/styles/app-sections.css`（單一 @import，減少 dev 請求數）。
 * 需調整區塊順序或拆分時：還原 `src/index.css` 多行 @import 並刪除此流程。
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const root = join(process.cwd(), 'src', 'styles')
const files = [
  'nav',
  'hero',
  'home-sf',
  'about',
  'products',
  'modules',
  'modules-panel',
  'showcase',
  'workflow-faq',
  'contact',
  'models-section',
  'model-detail',
  'footer',
  'realms',
  'backup',
]

let out =
  '/* Merged home section styles — generated by scripts/merge-app-sections-css.mjs */\n'

for (const f of files) {
  out += `\n/* ========== ${f}.css ========== */\n`
  out += readFileSync(join(root, `${f}.css`), 'utf8')
  if (!out.endsWith('\n')) out += '\n'
}

writeFileSync(join(root, 'app-sections.css'), out)
console.log('Wrote app-sections.css from', files.length, 'sources')
